# =========================================================================
# TITAN HARDENED STRONGSWAN CONFIGURATION (swanctl.conf)
# Target File: Live_Capture_Wi-Fi.pcap | Active Endpoints: 10.10.10.1 <-> 10.10.10.2
# [REFERENCE HARDENING BLUEPRINT: Pre-Established IPsec Stream]
# Target Endpoints: 10.10.10.1 <-> 10.10.10.2 | Standards: NIST SP 800-77 Rev 1 & NSA CNSA 2.0
# =========================================================================

connections {
    titan-tunnel {
        local_addrs  = 10.10.10.1
        remote_addrs = 10.10.10.2

        local {
            auth = psk
            id   = 10.10.10.1
        }
        remote {
            auth = psk
            id   = 10.10.10.2
        }

        children {
            titan-child-sa {
                local_ts  = 10.10.10.1/32
                remote_ts = 10.10.10.2/32

                # Phase 2 ESP Proposal: NSA CNSA 2.0 AES-256-GCM AEAD
                esp_proposals = aes256gcm16-prfsha384-ecp384-curve25519!

                # Strict RFC 4301 Tunnel Mode & Monotonic Sequence Anti-Replay
                mode = tunnel
                rekey_time = 3600s
                dpd_action = restart
            }
        }

        # Phase 1 IKEv2 Proposal: Hybrid ML-KEM / Curve25519 Key Exchange
        version = 2
        proposals = aes256gcm16-prfsha384-ecp384-curve25519-modp3072!
    }
}

